grid=[[1]*19 for _ in range(13)]
# original template
stamp=[[1,4,1],[1,5,1],[9,9,3],[7,5,5],[1,7,1]]
# Save template then apply translated stamp at isolated 6 markers
markers=[(2,1),(3,17),(5,5),(9,3),(9,16)]
for r,c in markers:
    for dr in range(-2,3):
        for dc in range(-1,2):
            grid[r+dr][c+dc]=stamp[dr+2][dc+1]
# place original template bbox rows4:9 cols10:13
for i,row in enumerate(stamp):
    for j,val in enumerate(row):
        grid[4+i][10+j]=val
print('\n'.join(' '.join(map(str,row)) for row in grid))
print(len(grid),len(grid[0]))
